import React, { useState, useEffect } from "react";
import { BASE_URL } from "../config";

function CustomerRegistrationForm({ selectedCustomer, onCreate, onUpdate }) {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    customerType: "",
  });

  // ✅ Load customer data when editing
  useEffect(() => {
    if (selectedCustomer) {
      setFormData(selectedCustomer);
    } else {
      setFormData({
        firstName: "",
        lastName: "",
        email: "",
        phoneNumber: "",
        customerType: "",
      });
    }
  }, [selectedCustomer]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      let response;

      if (selectedCustomer) {
        // ✅ Update customer
        response = await fetch(`${BASE_URL}/api/customers/${selectedCustomer.id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (!response.ok) throw new Error("Failed to update customer");

        const updated = await response.json();
        onUpdate(updated); // 🔄 update parent state
      } else {
        // ✅ Create new customer
        response = await fetch(`${BASE_URL}/api/customers`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (!response.ok) throw new Error("Failed to create customer");

        const created = await response.json();
        onCreate(created); // 🔄 add to parent list
      }

      // ✅ Reset form after success
      setFormData({
        firstName: "",
        lastName: "",
        email: "",
        phoneNumber: "",
        customerType: "",
      });
    } catch (error) {
      console.error("Error saving customer:", error);
      alert("Something went wrong. Please try again.");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="form-container">
      <h2>{selectedCustomer ? "Update Customer" : "Register Customer"}</h2>

      <input
        type="text"
        name="firstName"
        placeholder="First Name"
        value={formData.firstName}
        onChange={handleChange}
        required
      />

      <input
        type="text"
        name="lastName"
        placeholder="Last Name"
        value={formData.lastName}
        onChange={handleChange}
        required
      />

      <input
        type="email"
        name="email"
        placeholder="Email"
        value={formData.email}
        onChange={handleChange}
        required
      />

      <input
        type="text"
        name="phoneNumber"
        placeholder="Phone Number"
        value={formData.phoneNumber}
        onChange={handleChange}
      />

      <select
        name="customerType"
        value={formData.customerType}
        onChange={handleChange}
      >
        <option value="">Select type</option>
        <option value="Premium">Premium</option>
        <option value="Standard">Standard</option>
      </select>

      <button type="submit">
        {selectedCustomer ? "Update" : "Register"}
      </button>
    </form>
  );
}

export default CustomerRegistrationForm;
